using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
// In .NET 9+ there is a generic helper that avoids the cast:
// JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
// However the generic overload is an extension planned for later previews;
// the approach below uses TryGetTypeInfo which *is* available.

Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind = {personInfo.Kind}");

// 2) Probe without throwing: TryGetTypeInfo returns false if not available
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo(Person) => found={found}, info is null={info is null}");

// Now try a type that has NO resolver registered (empty resolver)
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};
// Remove the resolver to simulate "not available"
emptyOptions.TypeInfoResolver = null!;

bool found2 = emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2);
Console.WriteLine($"TryGetTypeInfo(Person) on empty resolver => found={found2}, info is null={info2 is null}");

public record Person(string Name, int Age);

